func relDiff(a, b float64) float64 {
        denom := math.Max(math.Abs(a), math.Abs(b))
        if denom < 1e-300 {
                return 0
        }
        return math.Abs(a-b) / denom
}

func modeString(m ComparisonMode) string {
        switch m {
        case ModeExact:
                return "exact"
        case ModeTolerance:
                return "tolerance"
        default:
                return "unknown"
        }
}
